+'use client';
+
+import { type ChangeEvent, type FormEvent, useCallback, useRef, useState } from 'react';
+import { Paperclip, Send, StopCircle } from 'lucide-react';
+import { useTranslations } from 'next-intl';
+import { toast } from 'sonner';
+
+import { Button } from '@/components/ui/button';
+import { Input } from '@/components/ui/input';
+import type { ImageObject } from '@/components/canvas/types';
+import {
+  type ChatAttachment,
+  MAX_CHAT_ATTACHMENTS,
+  resizeImageToDataUrl,
+} from '@/lib/chat-image-utils';
+
+import { ChatCanvasImagePopover } from './chat-canvas-image-popover';
+import { ChatImageAttachmentArea } from './chat-image-attachment-area';
+
+interface ChatFooterFormProps {
+  input: string;
+  handleInputChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
+  onSubmit: (e: React.FormEvent<HTMLFormElement>, attachments: ChatAttachment[]) => void;
+  isDisabled: boolean;
+  isProcessing: boolean;
+  onStop: () => void;
+}
+
+function getContentTypeFromUrl(url: string): string {
+  const extension = url.split('.').pop()?.split('?')[0]?.toLowerCase();
+  switch (extension) {
+    case 'png':
+      return 'image/png';
+    case 'webp':
+      return 'image/webp';
+    case 'gif':
+      return 'image/gif';
+    default:
+      return 'image/jpeg';
+  }
+}
+
+export function ChatFooterForm({
+  input,
+  handleInputChange,
+  onSubmit,
+  isDisabled,
+  isProcessing,
+  onStop
+}: ChatFooterFormProps) {
+  const t = useTranslations('Canvas.chat');
+  const [attachments, setAttachments] = useState<ChatAttachment[]>([]);
+  const fileInputRef = useRef<HTMLInputElement>(null);
+
+  const canSubmit = input.trim() !== '' || attachments.length > 0;
+
+  // Count canvas image attachments for enable/disable logic
+  const attachedCanvasImageIds = new Set(
+    attachments.filter((a) => a.source === 'canvas').map((a) => a.id)
+  );
+  const canvasImageAttachmentCount = attachedCanvasImageIds.size;
+
+  const addAttachment = useCallback(
+    (attachment: ChatAttachment) => {
+      setAttachments((prev) => {
+        if (prev.length >= MAX_CHAT_ATTACHMENTS) {
+          toast.error(t('imageAttachment.maxImagesReached', { max: String(MAX_CHAT_ATTACHMENTS) }));
+          return prev;
+        }
+        return [...prev, attachment];
+      });
+    },
+    [t]
+  );
+
+  const removeAttachment = useCallback((id: string) => {
+    setAttachments((prev) => prev.filter((a) => a.id !== id));
+  }, []);
+
+  const handleFileSelect = useCallback(
+    async (e: ChangeEvent<HTMLInputElement>) => {
+      const files = e.target.files;
+      if (!files) return;
+
+      for (const file of Array.from(files)) {
+        if (!file.type.startsWith('image/')) {
+          toast.error(t('imageAttachment.invalidFileType'));
+          continue;
+        }
+
+        try {
+          const dataUrl = await resizeImageToDataUrl(file);
+          addAttachment({
+            id: crypto.randomUUID(),
+            name: file.name,
+            contentType: 'image/jpeg',
+            url: dataUrl,
+            source: 'upload',
+          });
+        } catch {
+          toast.error(t('imageAttachment.invalidFileType'));
+        }
+      }
+
+      if (fileInputRef.current) {
+        fileInputRef.current.value = '';
+      }
+    },
+    [addAttachment, t]
+  );
+
+  const handleCanvasImageSelect = useCallback(
+    (image: ImageObject) => {
+      setAttachments((prev) => {
+        // Check if this image is already attached (toggle behavior)
+        const isAlreadyAttached = prev.some((a) => a.id === image.id && a.source === 'canvas');
+        
+        if (isAlreadyAttached) {
+          // Toggle OFF: remove the image
+          return prev.filter((a) => a.id !== image.id);
+        } else {
+          // Toggle ON: add the image
+          if (prev.length >= MAX_CHAT_ATTACHMENTS) {
+            toast.error(t('imageAttachment.maxImagesReached', { max: String(MAX_CHAT_ATTACHMENTS) }));
+            return prev;
+          }
+          
+          const src = Array.isArray(image.src) ? image.src[0] : image.src;
+          const contentType = getContentTypeFromUrl(src);
+          
+          return [...prev, {
+            id: image.id,
+            name: image.userPrompt ?? 'Canvas image',
+            contentType,
+            url: src,
+            source: 'canvas',
+          }];
+        }
+      });
+    },
+    [t]
+  );
+
+  const handleFormSubmit = useCallback(
+    (e: FormEvent<HTMLFormElement>) => {
+      e.preventDefault();
+      if (!canSubmit) return;
+      onSubmit(e, attachments);
+      setAttachments([]);
+    },
+    [attachments, canSubmit, onSubmit]
+  );
+
+  // Enable popover if: not disabled AND (can add more images OR can remove existing canvas images)
+  const isPopoverDisabled = isDisabled || (
+    attachments.length >= MAX_CHAT_ATTACHMENTS && canvasImageAttachmentCount === 0
+  );
+
+  return (
+    <div className="flex flex-col gap-1">
+      <ChatImageAttachmentArea attachments={attachments} onRemove={removeAttachment} />
+      <form onSubmit={handleFormSubmit} className="flex items-center space-x-2">
+        <input
+          ref={fileInputRef}
+          type="file"
+          accept="image/*"
+          multiple
+          className="hidden"
+          onChange={handleFileSelect}
+        />
+        <Button
+          type="button"
+          variant="ghost"
+          size="icon"
+          className="h-8 w-8 flex-shrink-0"
+          onClick={() => fileInputRef.current?.click()}
+          disabled={isDisabled || attachments.length >= MAX_CHAT_ATTACHMENTS}
+          title={t('imageAttachment.addImage')}
+        >
+          <Paperclip className="h-4 w-4" />
+        </Button>
+        <ChatCanvasImagePopover
+          onSelectImage={handleCanvasImageSelect}
+          disabled={isPopoverDisabled}
+          attachedImageIds={attachedCanvasImageIds}
+        />
+        <Input
+          value={input}
+          onChange={handleInputChange}
+          placeholder={t('placeholder')}
+          className="flex-1"
+          disabled={isDisabled}
+        />
+        {isProcessing ? (
+          <Button
+            type="button"
+            size="icon"
+            variant="destructive"
+            onClick={onStop}
+            title={t('stopGeneration')}
+          >
+            <StopCircle className="h-4 w-4" />
+          </Button>
+        ) : (
+          <Button type="submit" size="icon" disabled={!canSubmit}>
+            <Send className="h-4 w-4" />
+          </Button>
+        )}
+      </form>
+    </div>
+  );
+}
