+'use client';
+
+import { useCallback, useEffect, useRef, useState } from 'react';
+import { ChevronLeft, ChevronRight, X } from 'lucide-react';
+import { useTranslations } from 'next-intl';
+
+import type { ChatAttachment } from '@/lib/chat-image-utils';
+
+interface ChatImageAttachmentAreaProps {
+  attachments: ChatAttachment[];
+  onRemove: (id: string) => void;
+}
+
+export function ChatImageAttachmentArea({
+  attachments,
+  onRemove,
+}: ChatImageAttachmentAreaProps) {
+  const t = useTranslations('Canvas.chat');
+  const scrollRef = useRef<HTMLDivElement>(null);
+  const [canScrollLeft, setCanScrollLeft] = useState(false);
+  const [canScrollRight, setCanScrollRight] = useState(false);
+
+  const updateScrollState = useCallback(() => {
+    const el = scrollRef.current;
+    if (!el) return;
+    setCanScrollLeft(el.scrollLeft > 1);
+    setCanScrollRight(el.scrollLeft + el.clientWidth < el.scrollWidth - 1);
+  }, []);
+
+  // Update on attachment count changes (with rAF to ensure DOM is painted)
+  useEffect(() => {
+    const id = requestAnimationFrame(updateScrollState);
+    return () => cancelAnimationFrame(id);
+  }, [attachments.length, updateScrollState]);
+
+  // Listen to scroll events (scroll fires during animation, scrollend fires after)
+  useEffect(() => {
+    const el = scrollRef.current;
+    if (!el) return;
+    el.addEventListener('scroll', updateScrollState, { passive: true });
+    el.addEventListener('scrollend', updateScrollState);
+    return () => {
+      el.removeEventListener('scroll', updateScrollState);
+      el.removeEventListener('scrollend', updateScrollState);
+    };
+  }, [updateScrollState]);
+
+  // Watch for resize changes (e.g. container width changes)
+  useEffect(() => {
+    const el = scrollRef.current;
+    if (!el) return;
+    const observer = new ResizeObserver(updateScrollState);
+    observer.observe(el);
+    return () => observer.disconnect();
+  }, [updateScrollState]);
+
+  const scroll = useCallback((direction: 'left' | 'right') => {
+    const el = scrollRef.current;
+    if (!el) return;
+    const amount = direction === 'left' ? -128 : 128;
+    el.scrollBy({ left: amount, behavior: 'smooth' });
+
+    // Poll scroll position during smooth animation to update arrow state
+    let lastLeft = el.scrollLeft;
+    const poll = () => {
+      if (!scrollRef.current) return;
+      updateScrollState();
+      if (scrollRef.current.scrollLeft !== lastLeft) {
+        lastLeft = scrollRef.current.scrollLeft;
+        requestAnimationFrame(poll);
+      }
+    };
+    requestAnimationFrame(poll);
+  }, [updateScrollState]);
+
+  if (attachments.length === 0) return null;
+
+  const hasOverflow = canScrollLeft || canScrollRight;
+
+  return (
+    <div className="relative overflow-hidden">
+      {hasOverflow && (
+        <button
+          type="button"
+          onClick={() => scroll('left')}
+          className={`absolute left-0 top-1/2 -translate-y-1/2 z-10 h-10 w-6 flex items-center justify-center bg-background/80 hover:bg-background border border-border rounded-r-md transition-opacity ${
+            canScrollLeft ? 'opacity-100' : 'opacity-30'
+          }`}
+        >
+          <ChevronLeft className="h-4 w-4" />
+        </button>
+      )}
+      <div
+        ref={scrollRef}
+        className="flex gap-2 px-2 py-1.5 overflow-x-auto no-scrollbar min-w-0"
+      >
+        {attachments.map((attachment, index) => (
+          <div
+            key={attachment.id}
+            className="relative flex-shrink-0 w-14 h-14 rounded-md overflow-hidden border border-border group"
+          >
+            <img
+              src={attachment.url}
+              alt={attachment.name}
+              className="w-full h-full object-cover"
+            />
+            <div className="absolute top-0 left-0 min-w-[1.125rem] h-[1.125rem] flex items-center justify-center bg-black/60 text-white text-[10px] font-semibold rounded-br-md px-0.5">
+              {index + 1}
+            </div>
+            <button
+              type="button"
+              onClick={() => onRemove(attachment.id)}
+              className="absolute top-0 right-0 p-0.5 bg-background/80 rounded-bl-md opacity-0 group-hover:opacity-100 transition-opacity"
+              title={t('imageAttachment.removeImage')}
+            >
+              <X className="h-3 w-3" />
+            </button>
+            <div
+              className={`absolute bottom-0.5 left-0.5 w-1.5 h-1.5 rounded-full ${
+                attachment.source === 'canvas' ? 'bg-blue-400' : 'bg-green-400'
+              }`}
+            />
+          </div>
+        ))}
+      </div>
+      {hasOverflow && (
+        <button
+          type="button"
+          onClick={() => scroll('right')}
+          className={`absolute right-0 top-1/2 -translate-y-1/2 z-10 h-10 w-6 flex items-center justify-center bg-background/80 hover:bg-background border border-border rounded-l-md transition-opacity ${
+            canScrollRight ? 'opacity-100' : 'opacity-30'
+          }`}
+        >
+          <ChevronRight className="h-4 w-4" />
+        </button>
+      )}
+    </div>
+  );
+}
