+import { describe, it, expect, beforeEach, vi } from 'vitest';
+import { renderHook, act } from '@testing-library/react';
+import { useState, useCallback } from 'react';
+import type { ImageObject } from '@/components/canvas/types';
+import type { ChatAttachment } from '@/lib/chat-image-utils';
+
+// Mock the utility functions
+vi.mock('@/lib/chat-image-utils', () => ({
+  MAX_CHAT_ATTACHMENTS: 16,
+  resizeImageToDataUrl: vi.fn(),
+}));
+
+// Test helper: simulate the ChatFooterForm logic
+function createChatFooterFormLogic() {
+  let attachments: ChatAttachment[] = [];
+  
+  const addAttachment = (attachment: ChatAttachment) => {
+    if (attachments.length >= 16) {
+      throw new Error('MAX_CHAT_ATTACHMENTS_REACHED');
+    }
+    attachments = [...attachments, attachment];
+  };
+
+  const removeAttachment = (id: string) => {
+    attachments = attachments.filter((a) => a.id !== id);
+  };
+
+  const handleCanvasImageSelect = (image: ImageObject) => {
+    const isAlreadyAttached = attachments.some((a) => a.id === image.id && a.source === 'canvas');
+    
+    if (isAlreadyAttached) {
+      // Toggle OFF: remove the image
+      removeAttachment(image.id);
+    } else {
+      // Toggle ON: add the image
+      const src = Array.isArray(image.src) ? image.src[0] : image.src;
+      const contentType = src.includes('.png') ? 'image/png' : 'image/jpeg';
+      
+      addAttachment({
+        id: image.id,
+        name: image.userPrompt ?? 'Canvas image',
+        contentType,
+        url: src,
+        source: 'canvas',
+      });
+    }
+  };
+
+  return {
+    get attachments() { return attachments; },
+    addAttachment,
+    removeAttachment,
+    handleCanvasImageSelect,
+  };
+}
+
+function createMockImageObject(id: string, src: string): ImageObject {
+  return {
+    id,
+    type: 'image',
+    position: { x: 0, y: 0 },
+    width: 100,
+    height: 100,
+    visible: true,
+    isLocked: false,
+    src,
+    userPrompt: 'Test image',
+    rotation: 0,
+    children: [],
+    parentId: undefined,
+  } as ImageObject;
+}
+
+describe('ChatFooterForm - Image Attachment Toggle', () => {
+  let logic: ReturnType<typeof createChatFooterFormLogic>;
+
+  beforeEach(() => {
+    logic = createChatFooterFormLogic();
+  });
+
+  // Test 1: First click adds the image
+  it('should add image on first click', () => {
+    const image = createMockImageObject('img-1', 'https://example.com/image.jpg');
+    
+    logic.handleCanvasImageSelect(image);
+    
+    expect(logic.attachments).toHaveLength(1);
+    expect(logic.attachments[0].id).toBe('img-1');
+    expect(logic.attachments[0].source).toBe('canvas');
+  });
+
+  // Test 2: Second click on same image removes it (toggle)
+  it('should remove image on second click (toggle off)', () => {
+    const image = createMockImageObject('img-1', 'https://example.com/image.jpg');
+    
+    logic.handleCanvasImageSelect(image);
+    expect(logic.attachments).toHaveLength(1);
+    
+    logic.handleCanvasImageSelect(image);
+    expect(logic.attachments).toHaveLength(0);
+  });
+
+  // Test 3: Clicking different image adds it while first stays
+  it('should allow multiple images from different clicks', () => {
+    const image1 = createMockImageObject('img-1', 'https://example.com/image1.jpg');
+    const image2 = createMockImageObject('img-2', 'https://example.com/image2.jpg');
+    
+    logic.handleCanvasImageSelect(image1);
+    logic.handleCanvasImageSelect(image2);
+    
+    expect(logic.attachments).toHaveLength(2);
+    expect(logic.attachments.map((a) => a.id)).toEqual(['img-1', 'img-2']);
+  });
+
+  // Test 4: Toggle off when attached
+  it('should support toggle pattern: on -> off -> on', () => {
+    const image = createMockImageObject('img-1', 'https://example.com/image.jpg');
+    
+    // First click: add
+    logic.handleCanvasImageSelect(image);
+    expect(logic.attachments).toHaveLength(1);
+    
+    // Second click: remove
+    logic.handleCanvasImageSelect(image);
+    expect(logic.attachments).toHaveLength(0);
+    
+    // Third click: add again
+    logic.handleCanvasImageSelect(image);
+    expect(logic.attachments).toHaveLength(1);
+  });
+
+  // Test 5: PNG image gets correct content type
+  it('should detect PNG image content type', () => {
+    const image = createMockImageObject('img-png', 'https://example.com/image.png');
+    
+    logic.handleCanvasImageSelect(image);
+    
+    expect(logic.attachments[0].contentType).toBe('image/png');
+  });
+
+  // Test 6: JPEG image gets correct content type
+  it('should default to JPEG for unknown extensions', () => {
+    const image = createMockImageObject('img-jpg', 'https://example.com/image.jpg');
+    
+    logic.handleCanvasImageSelect(image);
+    
+    expect(logic.attachments[0].contentType).toBe('image/jpeg');
+  });
+
+  // Test 7: Max attachments still enforced
+  it('should throw when max attachments reached', () => {
+    const images = Array.from({ length: 16 }, (_, i) =>
+      createMockImageObject(`img-${i}`, `https://example.com/image${i}.jpg`)
+    );
+
+    images.forEach((img) => logic.handleCanvasImageSelect(img));
+    
+    expect(logic.attachments).toHaveLength(16);
+    
+    const newImage = createMockImageObject('img-new', 'https://example.com/new.jpg');
+    expect(() => logic.handleCanvasImageSelect(newImage)).toThrow('MAX_CHAT_ATTACHMENTS_REACHED');
+  });
+});
