+'use client';
+
+import { Check, ImageIcon } from 'lucide-react';
+import { useTranslations } from 'next-intl';
+
+import { Button } from '@/components/ui/button';
+import {
+  Popover,
+  PopoverContent,
+  PopoverTrigger,
+} from '@/components/ui/popover';
+import { type ImageObject, isImageObject } from '@/components/canvas/types';
+import { useCanvasStore } from '@/store/canvas-store';
+
+interface ChatCanvasImagePopoverProps {
+  onSelectImage: (image: ImageObject) => void;
+  disabled?: boolean;
+  attachedImageIds?: Set<string>;
+}
+
+export function ChatCanvasImagePopover({
+  onSelectImage,
+  disabled,
+  attachedImageIds,
+}: ChatCanvasImagePopoverProps) {
+  const t = useTranslations('Canvas.chat');
+  const canvasObjects = useCanvasStore((state) => state.canvasObjects);
+
+  const imageObjects = canvasObjects.filter(isImageObject).filter((obj) => {
+    const src = Array.isArray(obj.src) ? obj.src[0] : obj.src;
+    if (!src) return false;
+    try {
+      const parsed = new URL(src);
+      return ['http:', 'https:', 'data:', 'blob:'].includes(parsed.protocol);
+    } catch {
+      return false;
+    }
+  });
+
+  return (
+    <Popover>
+      <PopoverTrigger asChild>
+        <Button
+          variant="ghost"
+          size="icon"
+          className="h-8 w-8"
+          disabled={disabled}
+          title={t('imageAttachment.addFromCanvas')}
+        >
+          <ImageIcon className="h-4 w-4" />
+        </Button>
+      </PopoverTrigger>
+      <PopoverContent side="top" align="start" className="w-64 p-2">
+        {imageObjects.length === 0 ? (
+          <p className="text-sm text-muted-foreground text-center py-4">
+            {t('imageAttachment.noCanvasImages')}
+          </p>
+        ) : (
+          <div className="grid grid-cols-3 gap-1.5 max-h-48 overflow-y-auto">
+            {imageObjects.map((image) => {
+              const src = Array.isArray(image.src)
+                ? image.src[0]
+                : image.src;
+              const isAttached = attachedImageIds?.has(image.id) ?? false;
+
+              return (
+                <button
+                  key={image.id}
+                  type="button"
+                  onClick={() => onSelectImage(image)}
+                  className="relative aspect-square rounded-md overflow-hidden border border-border hover:border-primary transition-colors"
+                >
+                  <img
+                    src={src}
+                    alt=""
+                    className="w-full h-full object-cover"
+                  />
