index 0000000..107f318
--- /dev/null
+++ b/tests/unit/lib/chat-image-utils.test.ts
@@ -0,0 +1,199 @@
+import { describe, it, expect, beforeEach, vi } from 'vitest';
+
+import {
+  MAX_CHAT_ATTACHMENTS,
+  resizeImageToDataUrl
+} from '@/lib/chat-image-utils';
+
+// ---------------------------------------------------------------------------
+// Mocks
+// ---------------------------------------------------------------------------
+
+let capturedOnload: (() => void) | null = null;
+let capturedOnerror: (() => void) | null = null;
+let capturedSrc: string | null = null;
+
+const mockImageInstance = {
+  set onload(fn: () => void) {
+    capturedOnload = fn;
+  },
+  set onerror(fn: () => void) {
+    capturedOnerror = fn;
+  },
+  set src(value: string) {
+    capturedSrc = value;
+  },
+  get src() {
+    return capturedSrc ?? '';
+  },
+  width: 0,
+  height: 0
+};
+
+vi.stubGlobal(
+  'Image',
+  vi.fn(() => mockImageInstance)
+);
+
+const mockDrawImage = vi.fn();
+const mockToDataURL = vi.fn(() => 'data:image/jpeg;base64,mock');
+const mockGetContext = vi.fn();
+
+const mockCanvasElement = {
+  width: 0,
+  height: 0,
+  getContext: mockGetContext,
+  toDataURL: mockToDataURL
+};
+
+const originalCreateElement = document.createElement.bind(document);
+vi.spyOn(document, 'createElement').mockImplementation((tag: string) => {
+  if (tag === 'canvas') {
+    return mockCanvasElement as unknown as HTMLCanvasElement;
+  }
+  return originalCreateElement(tag);
+});
+
+const mockCreateObjectURL = vi.fn(() => 'blob:mock-url');
+const mockRevokeObjectURL = vi.fn();
+vi.stubGlobal('URL', {
+  ...URL,
+  createObjectURL: mockCreateObjectURL,
+  revokeObjectURL: mockRevokeObjectURL
+});
+
+// ---------------------------------------------------------------------------
+// Helpers
+// ---------------------------------------------------------------------------
+
+function createFakeFile(name: string): File {
+  return new File(['fake'], name, { type: 'image/png' });
+}
+
+/** Simulate the Image onload with the given natural dimensions. */
+function triggerLoad(width: number, height: number) {
+  mockImageInstance.width = width;
+  mockImageInstance.height = height;
+  capturedOnload!();
+}
+
+function triggerError() {
+  capturedOnerror!();
+}
+
+// ---------------------------------------------------------------------------
+// Tests
+// ---------------------------------------------------------------------------
+
+describe('chat-image-utils', () => {
+  beforeEach(() => {
+    vi.clearAllMocks();
+    capturedOnload = null;
+    capturedOnerror = null;
+    capturedSrc = null;
+    mockGetContext.mockReturnValue({ drawImage: mockDrawImage });
+  });
+
+  // 1. Constant value
+  it('MAX_CHAT_ATTACHMENTS is 16', () => {
+    expect(MAX_CHAT_ATTACHMENTS).toBe(16);
+  });
+
+  // 2. Small image — no resize
+  it('does not resize an image smaller than 1024px', async () => {
+    const file = createFakeFile('small.png');
+    const promise = resizeImageToDataUrl(file);
+
+    triggerLoad(800, 600);
+
+    await promise;
+
+    expect(mockCanvasElement.width).toBe(800);
+    expect(mockCanvasElement.height).toBe(600);
+  });
+
+  // 3. Large landscape image
+  it('scales a 2048x1536 landscape image to 1024x768', async () => {
+    const file = createFakeFile('landscape.png');
+    const promise = resizeImageToDataUrl(file);
+
+    triggerLoad(2048, 1536);
+
+    await promise;
+
+    expect(mockCanvasElement.width).toBe(1024);
+    expect(mockCanvasElement.height).toBe(768);
+  });
+
+  // 4. Tall portrait image
+  it('scales a 600x2000 portrait image to 307x1024', async () => {
+    const file = createFakeFile('portrait.png');
+    const promise = resizeImageToDataUrl(file);
+
+    triggerLoad(600, 2000);
+
+    await promise;
+
+    expect(mockCanvasElement.width).toBe(307);
+    expect(mockCanvasElement.height).toBe(1024);
+  });
+
+  // 5. Image load error
+  it('rejects when the image fails to load', async () => {
+    const file = createFakeFile('broken.png');
+    const promise = resizeImageToDataUrl(file);
+
+    triggerError();
+
+    await expect(promise).rejects.toThrow('Failed to load image: broken.png');
+  });
+
+  // 6. Canvas context null
+  it('rejects when canvas 2d context is null', async () => {
+    mockGetContext.mockReturnValue(null);
+
+    const file = createFakeFile('no-ctx.png');
+    const promise = resizeImageToDataUrl(file);
+
+    triggerLoad(100, 100);
+
+    await expect(promise).rejects.toThrow(
+      'Failed to get canvas 2d context'
+    );
+  });
+
+  // 7. Always calls toDataURL with 'image/jpeg' and 0.7
+  it('calls toDataURL with image/jpeg and 0.7 quality', async () => {
+    const file = createFakeFile('quality.png');
+    const promise = resizeImageToDataUrl(file);
+
+    triggerLoad(500, 500);
+
+    const result = await promise;
+
+    expect(mockToDataURL).toHaveBeenCalledWith('image/jpeg', 0.7);
+    expect(result).toBe('data:image/jpeg;base64,mock');
+  });
+
+  // 8. Revokes object URL after load
+  it('revokes the object URL after successful load', async () => {
+    const file = createFakeFile('revoke.png');
+    const promise = resizeImageToDataUrl(file);
+
+    triggerLoad(200, 200);
+
+    await promise;
+
+    expect(mockRevokeObjectURL).toHaveBeenCalledWith('blob:mock-url');
+  });
+
+  it('revokes the object URL after load error', async () => {
+    const file = createFakeFile('revoke-err.png');
+    const promise = resizeImageToDataUrl(file);
+
+    triggerError();
+
+    await expect(promise).rejects.toThrow();
+    expect(mockRevokeObjectURL).toHaveBeenCalledWith('blob:mock-url');
+  });
+});
